juce::String rejectionReason(mrs::ai::Error error){switch(error){case mrs::ai::Error::invalid_input:return "Invalid tool fields, IDs, range, overlap or size limit";case mrs::ai::Error::not_found:return "Target not found in the current project";case mrs::ai::Error::stale_context:return "Project changed; request uses an older context";case mrs::ai::Error::permission_denied:return "Not permitted by current AI permissions";case mrs::ai::Error::unsupported:return "Unsupported operation or target";default:return "Local validation refused the proposal";}}
class ChatInput final:public juce::TextEditor {
public:
    std::function<void()> submit;
    bool keyPressed(const juce::KeyPress& key) override {
        if(key.getKeyCode()==juce::KeyPress::returnKey){
            if(key.getModifiers().isShiftDown())insertTextAtCaret("\n");
            else if(submit)submit();return true;
        }
        return juce::TextEditor::keyPressed(key);
    }
};
