        output.setMultiLine(true);output.setReadOnly(true);output.setScrollbarsShown(true);output.setText("Sending shares project data, offline analysis summaries and recent conversation with your provider. Audio files remain local.\nProposals appear below for local review. MIDI draft Apply requires EDIT, stopped playback, loop off and explicit review. Select the target instrument track or MIDI clip before sending.\nOne call per message. Connection controls output token budget. Cost: unknown.");
        diff.setMultiLine(true);diff.setReadOnly(true);diff.setTitle("AI preview: before and after");addAndMakeVisible(diff);addAndMakeVisible(previewStatus);
