    aiapi::Config fields(){auto current=config;current.provider=provider.getText().trim();current.base=base.getText().trim();current.model=model.getText().trim();current.maxTokens=tokens.getSelectedId();current.validate();return current;}
    void appendMessage(const juce::String& role,const juce::String& message){
        transcript.add(role+"\n"+message.substring(0,32768));
        auto display=transcript.joinIntoString("\n\n----------------\n\n");
        while(transcript.size()>96||display.getNumBytesAsUTF8()>262144){transcript.remove(0);display=transcript.joinIntoString("\n\n----------------\n\n");}
        output.setText(display);output.moveCaretToEnd();
    }
    void updateButtons(){bool idle=active==0;for(auto* c:{&provider,&base,&model,&key})c->setEnabled(idle);tokens.setEnabled(idle);save.setEnabled(idle);test.setEnabled(idle);send.setEnabled(idle);analysisButton.setEnabled(idle);forget.setEnabled(true);cancel.setEnabled(!idle);updatePreview();}
    void renderDiff(){juce::String display,lastScope;for(const auto& change:preview->changes){juce::String field=change.property=="marker.name"?"Marker name":change.property=="marker.tick"?"Marker tick":change.property=="note.pitch"?"Note pitch":change.property=="note.velocity"?"Note velocity":change.property=="midi.clip"?"MIDI clip":change.property=="midi.note"?"MIDI note":change.property=="midi.cc"?"MIDI CC":change.property=="set_ara_bypass"?"ARA bypass":change.property=="attach_ara"?"ARA plugin":change.property=="open_ara_editor"?"ARA editor":change.property=="remove_ara"?"ARA binding":change.property=="reanalyse_ara"?"ARA analysis":text(change.property);auto value=[&](const std::string& data){return change.property=="marker.name"?juce::JSON::toString(juce::var(text(data)),true):text(data);};auto scope=text(change.scope).replace("\r","\\r").replace("\n","\\n").replace("\t","\\t");if(scope!=lastScope){display+=scope+"\n";lastScope=scope;}display+=juce::String(field)+": "+value(change.before)+" -> "+value(change.after)+"\n\n";}if(display.isEmpty())display="No changes";diff.setText(display);}
    void updatePreview(){apply.setEnabled(false);reject.setEnabled(false);rebuild.setEnabled(false);if(!preview){previewStatus.setText(active?"Pending response":"No proposal",juce::dontSendNotification);return;}
        if(preview->state()==mrs::ai::PreviewState::accepted){const bool writes=std::any_of(preview->plans.begin(),preview->plans.end(),[](const auto& p){return mrs::ai::tool_descriptor(p->call.tool)->project_write;});previewStatus.setText(writes?"Accepted - Undo available":"Accepted - editor action",juce::dontSendNotification);return;}
        if(preview->state()==mrs::ai::PreviewState::rejected){previewStatus.setText("Rejected - project unchanged",juce::dontSendNotification);return;}
        if(preview->state()==mrs::ai::PreviewState::failed){previewStatus.setText("Failed - project unchanged",juce::dontSendNotification);reject.setEnabled(true);rebuild.setEnabled(true);return;}
        if(preview->changes.empty()){previewStatus.setText("No changes - nothing to apply",juce::dontSendNotification);reject.setEnabled(true);return;}
        const auto result=owner.app.ai_preview_status(preview);reject.setEnabled(true);
        if(preview->state()==mrs::ai::PreviewState::stale||result.error==mrs::ai::Error::stale_context||result.block==mrs::ai::Block::preview){auto context=owner.app.ai_context();const bool sameSession=context.value&&context.value->key.project==preview->key.project&&context.value->key.session==preview->key.session;const bool canRefresh=sameSession&&context.value->key!=preview->key;previewStatus.setText(canRefresh?"Stale - refresh and review again":"Access/session changed - request again",juce::dontSendNotification);rebuild.setEnabled(canRefresh);return;}
        if(result.allowed()){previewStatus.setText("Preview - confirm shown changes",juce::dontSendNotification);apply.setEnabled(!active);return;}
        auto reason=result.block==mrs::ai::Block::mode?"SUGGEST: choose EDIT, then request again":result.block==mrs::ai::Block::midi_playback?"MIDI Apply: stop playback and turn loop off":result.block==mrs::ai::Block::midi_contract?"MIDI Apply unavailable":result.block==mrs::ai::Block::automatic_allowlist?"Tool is outside AUTO allowlist":result.block==mrs::ai::Block::live_performance||result.block==mrs::ai::Block::recording?"Stop performance / recording before Apply":"Access revoked or preview unavailable";previewStatus.setText(reason,juce::dontSendNotification);
    }
