        prompt.setText(juce::String::fromUTF8("С 1-го такта, длительность 2 такта"));key.setText("fixture-key");begin(false);drain();if(!remembered||conversation.turns.size()!=2)throw std::runtime_error(("GUI follow-up: turns="+juce::String(conversation.turns.size())+" remembered="+juce::String(remembered?1:0)+" messages="+fixtureMessages).toStdString());
