        for(auto kind:{mrs::ai::QueryKind::ara_capabilities,mrs::ai::QueryKind::ara_status}){mrs::ai::Query query;query.kind=kind;query.limit=16;query.byte_budget=2048;queries.push_back(query);}
        if(owner.selectedClip){const auto p=owner.project();const auto c=std::find_if(p->clips.begin(),p->clips.end(),[&](const auto& clip){return clip.id==*owner.selectedClip;});if(c!=p->clips.end()&&!c->midi){mrs::ai::Query query;query.kind=mrs::ai::QueryKind::ara_status;query.clip=c->id;query.limit=1;query.byte_budget=1024;queries.push_back(query);}}
#endif
        if(owner.selectedTrack){mrs::ai::Query q;q.kind=mrs::ai::QueryKind::tracks;q.id=owner.selectedTrack;q.limit=1;q.byte_budget=2048;queries.push_back(q);}if(owner.selectedClip){mrs::ai::Query q;q.kind=mrs::ai::QueryKind::clips;q.id=owner.selectedClip;q.limit=1;q.byte_budget=2048;queries.push_back(q);}
        if(owner.selectedClip){const auto p=owner.project();const auto clip=std::find_if(p->clips.begin(),p->clips.end(),[&](const auto& c){return c.id==*owner.selectedClip;});if(clip!=p->clips.end()&&clip->midi)for(auto kind:{mrs::ai::QueryKind::midi_notes,mrs::ai::QueryKind::midi_events}){mrs::ai::Query q;q.kind=kind;q.clip=*owner.selectedClip;q.limit=64;q.byte_budget=8192;queries.push_back(q);}}
