        mrs::ai::Request request;request.context=*context.value;request.input=input.toStdString();request.snapshot=snapshot.value;request.timeout=std::chrono::seconds(60);
        if(conversationAccess&&(!conversationAccess->access_valid()||conversationAccess->context.key.session!=context.value->key.session||current.base!=config.base||current.model!=config.model)){conversation.clear();conversationAccess.reset();}
        auto submitted=owner.app.request_ai(std::move(request),aiapi::task(current,secret,list,owner.app.ai_permissions().mode!=mrs::ai::PermissionMode::read,transport,list||localAnalysis?aiapi::Conversation{}:conversation,{list?nullptr:owner.app.ai_read_view(selection).value,list?std::vector<mrs::desktop::Application::AnalysisSource>{}:owner.app.ai_analysis_sources(),analysisCache,localAnalysis}));if(submitted.error!=mrs::ai::Error::none)throw std::runtime_error("AI worker refused request");
