std::unique_ptr<juce::Component> makeAiAssistant(Desktop& owner){return std::make_unique<AiAssistantPanel>(owner);}
void Desktop::aiAssistant(){sidebar=true;resizeBrowser(juce::jmax(browserWidth,420));browser->showAssistant();resized();repaint();}
void aiAssistantSmoke(Desktop& owner){aiapi::smoke();AiAssistantPanel assistant(owner);assistant.prompt.setText(juce::String::fromUTF8("Расскажи о проекте"));assistant.key.setText("fixture-key");assistant.transport=[](auto&,auto&,auto&,auto&,auto&){return aiapi::Reply{200,juce::String::fromUTF8(R"({"model":"fixture","choices":[{"message":{"content":"Тестовый ответ"},"finish_reason":"stop"}],"usage":{"prompt_tokens":10,"completion_tokens":5}})")};};assistant.begin(false);for(int pass=0;pass<200&&assistant.active;++pass){MSG msg{};while(PeekMessageW(&msg,nullptr,0,0,PM_REMOVE)){TranslateMessage(&msg);DispatchMessageW(&msg);}std::this_thread::sleep_for(std::chrono::milliseconds(10));}if(assistant.active||!assistant.output.getText().contains(juce::String::fromUTF8("Тестовый ответ")))throw std::runtime_error((juce::String("AI UI mock delivery: ")+assistant.state.getText()+" | "+assistant.output.getText()).toStdString());assistant.testProposals();assistant.testMidi();assistant.testConversation();assistant.testLocalAnalysis();for(auto scale:{1.f,1.5f}){auto image=assistant.createComponentSnapshot(assistant.getLocalBounds(),true,scale,juce::SoftwareImageType{});auto stream=juce::File::getCurrentWorkingDirectory().getChildFile(scale==1.f?"ai-assistant-100.png":"ai-assistant-150.png").createOutputStream();if(stream){stream->setPosition(0);stream->truncate();}if(!stream||!juce::PNGImageFormat().writeImageToStream(image,*stream))throw std::runtime_error("AI preview export");}
    const auto windowCount=owner.windows.size();owner.aiAssistant();auto* docked=dynamic_cast<AiAssistantPanel*>(owner.browser->assistantComponent());if(!docked||!docked->isVisible()||owner.windows.size()!=windowCount||!owner.browser->isParentOf(docked))throw std::runtime_error("Assistant belongs to Browser AI tab");
    if(owner.shortcutAllowedFor(&docked->prompt))throw std::runtime_error("Assistant typing blocks DAW shortcuts");owner.browser->showFiles(true);if(docked->isVisible())throw std::runtime_error("Files tab hides AI");owner.browser->showAssistant();if(owner.browser->assistantComponent()!=docked||!docked->isVisible())throw std::runtime_error("AI tab preserves component");
    for(const auto size:std::array<juce::Point<int>,3>{{{192,570},{404,720},{620,720}}})for(bool expanded:{false,true}){docked->connectionVisible=expanded;docked->setSize(size.x,size.y);docked->resized();for(auto* component:docked->getChildren())if(component->isVisible()&&!docked->getLocalBounds().contains(component->getBounds()))throw std::runtime_error("AI tab control bounds");if(docked->send.getBottom()!=docked->getHeight()-8||docked->prompt.getBottom()+6!=docked->send.getY())throw std::runtime_error("AI composer and Send anchored at bottom");}docked->connectionVisible=false;
    owner.resized();owner.browser->resized();docked->prompt.setText("Add a marker at tick 11520");docked->key.setText("fixture-key");docked->transport=[](auto&,auto&,auto&,auto&,auto&){return aiapi::Reply{200,R"({"model":"fixture","choices":[{"message":{"tool_calls":[{"function":{"name":"add_marker","arguments":"{\"name\":\"Verse\",\"tick\":11520}"}}]},"finish_reason":"tool_calls"}],"usage":{"prompt_tokens":1200,"completion_tokens":23}})"};};docked->begin(false);for(int pass=0;pass<200&&docked->active;++pass){std::this_thread::sleep_for(std::chrono::milliseconds(5));docked->timerCallback();}if(!docked->preview||!docked->apply.isEnabled())throw std::runtime_error("Browser local marker preview");
    // Deliver MenuBarModel's async mode update before taking an offscreen image.
    for(int pass=0;pass<20;++pass){MSG message{};while(PeekMessageW(&message,nullptr,0,0,PM_REMOVE)){TranslateMessage(&message);DispatchMessageW(&message);}std::this_thread::sleep_for(std::chrono::milliseconds(1));}
    if(!owner.getMenuBarNames().contains("AI: EDIT"))throw std::runtime_error("Browser preview has visible EDIT authority");
    if(docked->prompt.getText().isNotEmpty())throw std::runtime_error("Submitted composer remains empty after async text notifications");
    for(auto scale:{1.f,1.5f}){auto image=owner.createComponentSnapshot(owner.getLocalBounds(),true,scale,juce::SoftwareImageType{});auto stream=juce::File::getCurrentWorkingDirectory().getChildFile(scale==1.f?"ai-browser-preview-100.png":"ai-browser-preview-150.png").createOutputStream();if(!stream)throw std::runtime_error("Browser snapshot stream");stream->setPosition(0);stream->truncate();if(!juce::PNGImageFormat().writeImageToStream(image,*stream))throw std::runtime_error("Browser snapshot export");}
}
